"async function pollPrintfulV2MockupTasks(tasks) {",
"  let current = Array.isArray(tasks) ? tasks : [];",
"  const ids = current.map(t => Number(t?.id)).filter(Number.isInteger);",
"  if (!ids.length) return current;",
"  await new Promise(resolve => setTimeout(resolve, 2500));",
"  for (let attempt = 0; attempt < 20; attempt++) {",
"    const j = await printfulRequest('GET', '/v2/mockup-tasks?id=' + ids.join(','));",
"    const rows = Array.isArray(j.data) ? j.data : (j.data ? [j.data] : []);",
"    if (rows.length) current = rows;",
"    if (current.every(t => ['completed','failed'].includes(String(t?.status || '').toLowerCase()))) break;",
"    await new Promise(resolve => setTimeout(resolve, 1500));",
"  }",
"  return current;",
"}",
