"async function buildPrintfulFlatBatchMap(products, seedMap) {",
"  const flatMap = new Map(seedMap || []);",
"  const garments = products.filter(p => {",
"    if (!printfulNeedsGarmentOnlyMockup(p.name) || !Number.isInteger(Number(p.sync_product_id))) return false;",
"    const keys = new Set((p.variants || []).map(v => printfulVariantColourKey(v)).filter(Boolean));",
"    for (const colourKey of keys) if (!flatMap.has(String(p.sync_product_id) + ':' + colourKey)) return true;",
"    return false;",
"  });",
"  if (!garments.length) return flatMap;",
"",
"  const mineResponse = await printfulRequest('GET', '/v2/products?limit=100');",
"  const mine = Array.isArray(mineResponse.data) ? mineResponse.data : [];",
"  const bySync = new Map();",
"  for (const my of mine) {",
"    for (const pub of Array.isArray(my?.published_to_stores) ? my.published_to_stores : []) {",
"      const sid = Number(pub?.sync_product_id);",
"      if (Number.isInteger(sid)) bySync.set(sid, my);",
"    }",
"  }",
"",
"  const prepared = [];",
"  for (const p of garments) {",
"    const my = bySync.get(Number(p.sync_product_id));",
"    const myProductId = Number(my?.id);",
"    const catalogProductId = Number(my?.catalog_product_id);",
"    const placements = Array.isArray(my?.placements) ? my.placements.filter(Boolean) : [];",
"    if (!my || !Number.isInteger(myProductId) || !Number.isInteger(catalogProductId) || !placements.length) continue;",
"",
"    const variantsResponse = await printfulRequest('GET', '/v2/products/' + myProductId + '/variants?limit=100');",
"    const myVariants = Array.isArray(variantsResponse.data) ? variantsResponse.data : [];",
"    const myVariantByCatalog = new Map(myVariants.map(v => [Number(v.catalog_variant_id), Number(v.id)]).filter(([c,m]) => Number.isInteger(c) && Number.isInteger(m)));",
"    const representatives = [];",
"    const seenColours = new Set();",
"    for (const v of (p.variants || [])) {",
"      const colourKey = printfulVariantColourKey(v);",
"      const catalogId = Number(v.catalog_variant_id);",
"      const myVariantId = myVariantByCatalog.get(catalogId);",
"      if (!colourKey || seenColours.has(colourKey) || !Number.isInteger(catalogId) || !Number.isInteger(myVariantId)) continue;",
"      if (flatMap.has(String(p.sync_product_id) + ':' + colourKey)) { seenColours.add(colourKey); continue; }",
"      seenColours.add(colourKey);",
"      representatives.push({ colourKey, catalogId, myVariantId });",
"    }",
"    if (!representatives.length) continue;",
"",
"    const styleResponse = await printfulRequest('GET', '/v2/catalog-products/' + catalogProductId + '/mockup-styles?limit=100&default_mockup_styles=true&selling_region_name=uk');",
"    const groups = Array.isArray(styleResponse.data) ? styleResponse.data : [];",
"    const styles = groups.flatMap(g => (Array.isArray(g?.mockup_styles) ? g.mockup_styles : []).map(m => ({...m, placement:g.placement})));",
"    const flatFront = styles.find(m => /^flat$/i.test(String(m.category_name || '')) && /front/i.test(String(m.view_name || m.placement || '')));",
"    const flatAny = styles.find(m => /^flat$/i.test(String(m.category_name || '')));",
"    const chosen = flatFront || flatAny;",
"    if (!chosen?.id) continue;",
"",
"    const catalogToColour = new Map(representatives.map(r => [r.catalogId, r.colourKey]));",
"    prepared.push({",
"      product:p,",
"      style_id:Number(chosen.id),",
"      catalogToColour,",
"      request:{ source:'product', mockup_style_ids:[Number(chosen.id)], product_id:myProductId, variant_ids:representatives.map(r => r.myVariantId), placements }",
"    });",
"  }",
"",
"  for (let i = 0; i < prepared.length; i++) {",
"    const ref = prepared[i];",
"    const created = await printfulRequest('POST', '/v2/mockup-tasks', { format:'png', mockup_width_px:1200, products:[ref.request] });",
"    const tasks = Array.isArray(created.data) ? created.data : (created.data ? [created.data] : []);",
"    const finished = await pollPrintfulV2MockupTasks(tasks);",
"    const task = finished[0];",
"    if (String(task?.status || '').toLowerCase() === 'completed') {",
"      for (const row of Array.isArray(task?.catalog_variant_mockups) ? task.catalog_variant_mockups : []) {",
"        const catalogId = Number(row?.catalog_variant_id);",
"        const colourKey = ref.catalogToColour.get(catalogId);",
"        const mockups = Array.isArray(row?.mockups) ? row.mockups : [];",
"        const picked = mockups.find(m => Number(m?.style_id) === ref.style_id) || mockups[0] || null;",
"        const url = String(picked?.mockup_url || '').trim();",
"        if (colourKey && url) flatMap.set(String(ref.product.sync_product_id) + ':' + colourKey, url);",
"      }",
"    }",
"    if (i + 1 < prepared.length) await new Promise(resolve => setTimeout(resolve, 1500));",
"  }",
"  return flatMap;",
"}",
"",
"async function enrichPrintfulFlatProductMockups(products) {",
