"    products.push({",
"      sync_product_id: Number(product.id || summary.id),",
"      slug: 'pf-' + String(product.id || summary.id),",
"      name: String(product.name || summary.name || 'Afiléon Motorsport Product').trim(),",
"      description: String(product.description || 'Made-to-order Afiléon Motorsport product.'),",
"      price: Math.min(...prices),",
"      price_from: Math.min(...prices),",
"      product_only_url: null,",
"      mockup_url: variants.find(v => v.mockup_url)?.mockup_url || product.thumbnail_url || summary.thumbnail_url || null,",
"      image_url: variants.find(v => v.mockup_url)?.mockup_url || product.thumbnail_url || summary.thumbnail_url || null,",
"      stock: null,",
"      featured: true,",
"      collection: 'teamwear',",
"      variants",
"    });",
"  }",
"  return products;",
"}",
