const shopGalleryRoute = "\nconst PRINTFUL_GALLERY_TOKEN = process.env.PRINTFUL_GALLERY_API_TOKEN || PRINTFUL_API_TOKEN;\nasync function galleryPrintfulRequest(method,endpoint,body){\n  if(!PRINTFUL_GALLERY_TOKEN) throw Error('printful_gallery_token_missing');\n  const headers={Authorization:'Bearer '+PRINTFUL_GALLERY_TOKEN,'Content-Type':'application/json','X-PF-Store-Id':PRINTFUL_STORE_ID};\n  const controller=new AbortController();\n  const timer=setTimeout(()=>controller.abort(),25000);\n  try{\n    const response=await fetch('https://api.printful.com'+endpoint,{method,headers,body:body==null?undefined:JSON.stringify(body),signal:controller.signal});\n    let json={};try{json=await response.json()}catch{}\n    if(!response.ok) throw Error('Printful gallery '+response.status+' '+method+' '+endpoint+': '+String(json?.error?.message||json?.error||'request_failed').slice(0,180));\n    return json;\n  }finally{clearTimeout(timer)}\n}\nconst PRINTFUL_GALLERY_CACHE = new Map();\nconst PRINTFUL_GALLERY_RUNNING = new Map();\nconst PRINTFUL_GALLERY_SUCCESS_MS = 6 * 60 * 60 * 1000;\nconst PRINTFUL_GALLERY_FAILURE_MS = 15 * 60 * 1000;\nlet PRINTFUL_GALLERY_PRODUCTS = null;\nlet PRINTFUL_GALLERY_PRODUCTS_AT = 0;\nfunction galleryViewName(v) {\n  const s=String(v || '').toLowerCase();\n  if (s.includes('back')) return 'Back';\n  if (s.includes('left sleeve')) return 'Left sleeve';\n  if (s.includes('right sleeve')) return 'Right sleeve';\n  if (s.includes('left')) return 'Left side';\n  if (s.includes('right')) return 'Right side';\n  if (s.includes('side')) return 'Side';\n  if (s.includes('front')) return 'Front';\n  if (s.includes('top')) return 'Top';\n  return 'Product view';\n}\nasync function galleryMyProducts(sid) {\n  const r = await galleryPrintfulRequest('GET','/v2/products?store_product_ids='+encodeURIComponent(String(sid))+'&limit=10');\n  return Array.isArray(r?.data)?r.data:[];\n}\n\n\nasync function galleryMatchingTemplate(p,productId,variantId){\n  const needle=String(p.name||'').trim().toLowerCase().replace(/\\s+/g,' ');\n  if(!needle)return null;\n  const possible=[];\n  for(let page=0;page<3;page++){\n    const j=await galleryPrintfulRequest('GET','/product-templates?limit=100&offset='+(page*100));\n    const items=Array.isArray(j?.result?.items)?j.result.items:[];\n    for(const t of items){\n      const title=String(t.title||'').trim().toLowerCase().replace(/\\s+/g,' ');\n      if(title!==needle||Number(t.product_id)!==productId)continue;\n      if(!Array.isArray(t.available_variant_ids)||!t.available_variant_ids.map(Number).includes(variantId))continue;\n      possible.push(t);\n    }\n    if(items.length<100)break;\n  }\n  if(possible.length!==1) {\n    console.warn('Printful template fallback match count',String(p.slug),possible.length);\n    return null;\n  }\n  return possible[0];\n}\n\nasync function generateLegacyPrintfulGallery(p,v){\n  const variantId=Number(v.catalog_variant_id);\n  let catalogId=Number(v.catalog_product_id);\n  if(!catalogId||!Number.isInteger(catalogId)){\n    const visual=await printfulCatalogVariantVisual(variantId);\n    catalogId=Number(visual?.catalog_product_id);\n  }\n  if(!Number.isInteger(catalogId)||!Number.isInteger(variantId)||catalogId<=0||variantId<=0) throw Error('legacy_catalog_ids_missing');\n  const designs=(Array.isArray(v.design_files)&&v.design_files.length?v.design_files:(p.variants||[]).find(q=>Array.isArray(q.design_files)&&q.design_files.length)?.design_files)||[];\n  const files=designs.map(f=>({placement:String(f.placement||''),image_url:String(f.image_url||''),...(f.position&&typeof f.position==='object'?{position:f.position}:{})})).filter(f=>f.placement&&/^https:\\/\\//.test(f.image_url));\n  if(!files.length) throw Error('legacy_design_placements_missing');\n  let options=['Front','Back'];\n  let groups=['Flat'];\n  try {\n    const guide=await galleryPrintfulRequest('GET','/mockup-generator/printfiles/'+catalogId);\n    const data=guide?.result||{};\n    const opts=Array.isArray(data.options)?data.options:[];\n    const grp=Array.isArray(data.option_groups)?data.option_groups:[];\n    if(opts.length){\n      const requested=opts.filter(x=>/front|back|left|right|side/i.test(String(x)));\n      if(requested.length) options=requested.slice(0,6);\n      else options=[];\n    }\n    if(grp.length){\n      const matched=grp.find(x=>String(x).toLowerCase()==='flat');\n      groups=matched?[matched]:[grp[0]];\n    }\n  }catch(e){console.warn('Printful gallery style discovery unavailable',catalogId,String(e.message).slice(0,120))}\n  const body={variant_ids:[variantId],format:'jpg',width:1000,files, ...(groups.length?{option_groups:groups}:{}),...(options.length?{options}:{})};\n  let created;\n  try{created=await galleryPrintfulRequest('POST','/mockup-generator/create-task/'+catalogId,body)}\n  catch(e){\n    console.warn('Printful gallery retry without filters',catalogId,String(e.message).slice(0,180));\n    let template=null;\n    try{template=await galleryMatchingTemplate(p,catalogId,variantId)}catch(err){console.warn('Printful template lookup unavailable',String(p.slug),String(err.message).slice(0,180))}\n    if(template){\n      const templateBody={variant_ids:[variantId],format:'jpg',width:1000,product_template_id:Number(template.id)};\n      created=await galleryPrintfulRequest('POST','/mockup-generator/create-task/'+catalogId,templateBody);\n      console.log('Printful matching saved design template used',String(p.slug),Number(template.id));\n    }else{\n      delete body.options;\n      delete body.option_groups;\n      created=await galleryPrintfulRequest('POST','/mockup-generator/create-task/'+catalogId,body);\n    }\n  }\n  const key=String(created?.result?.task_key||'');\n  let task=created?.result||{};\n  for(let i=0;key&&!['completed','failed'].includes(String(task.status||'').toLowerCase())&&i<16;i++){\n    await new Promise(resolve=>setTimeout(resolve,1500));\n    task=(await galleryPrintfulRequest('GET','/mockup-generator/task?task_key='+encodeURIComponent(key)))?.result||task;\n  }\n  if(String(task?.status||'').toLowerCase()!=='completed') throw Error('legacy_task_'+String(task?.status||task?.error||'pending'));\n  const photos=[],seen=new Set();\n  function append(url,label){\n    const u=String(url||'').trim();\n    if(!/^https:\\/\\//.test(u)||seen.has(u))return;\n    seen.add(u);\n    photos.push({mockup_url:u,view:galleryViewName(label),color:v.color||null});\n  }\n  for(const m of Array.isArray(task.mockups)?task.mockups:[]){\n    if(Array.isArray(m.variant_ids)&&m.variant_ids.length&&!m.variant_ids.map(Number).includes(variantId))continue;\n    append(m.mockup_url,m.display_name||m.placement||'Front');\n    for(const extra of Array.isArray(m.extra)?m.extra:[])append(extra.url,extra.option||extra.title||extra.option_group);\n  }\n  if(!photos.length)throw Error('legacy_mockup_empty');\n  return photos.slice(0,10);\n}\n\nasync function generatePrintfulGallery(p, v) {\n  return generateLegacyPrintfulGallery(p,v);\n  const sid=Number(p.sync_product_id || String(p.slug).replace(/^pf-/, ''));\n  const catalogVariantId=Number(v.catalog_variant_id);\n  const all=await galleryMyProducts(sid);\n  const my=all.find(x=>Array.isArray(x.published_to_stores)&&x.published_to_stores.some(y=>Number(y.sync_product_id)===sid));\n  if(!my) throw Error('no_saved_printful_product_for_sync_id');\n  const savedHref=String(my?._links?.self?.href||'');\n  const hrefId=Number(savedHref.match(/\\/v2\\/products\\/(\\d+)/)?.[1]);\n  const myId=String(my.id||my.product_id||my.my_product_id||my?.product?.id||hrefId||'').trim();\n  let catalogId=Number(my.catalog_product_id||v.catalog_product_id);\n  if(!Number.isInteger(catalogId)||catalogId<=0){\n    const visual=await printfulCatalogVariantVisual(catalogVariantId);\n    catalogId=Number(visual?.catalog_product_id);\n  }\n  if(!myId||!Number.isInteger(catalogId)||catalogId<=0) {\n    console.error('Printful gallery unresolved saved IDs',sid,myId,catalogId,'fields',Object.keys(my).join(','),'idText',String(my.id||'').slice(0,80));\n    throw Error('missing_saved_product_id');\n  }\n  const variants=await galleryPrintfulRequest('GET','/v2/products/'+encodeURIComponent(myId)+'/variants?limit=100');\n  const myv=(Array.isArray(variants?.data)?variants.data:[]).find(x=>Number(x.catalog_variant_id)===catalogVariantId);\n  if(!myv) throw Error('selected_colour_variant_not_in_saved_product');\n  const stylesResponse=await galleryPrintfulRequest('GET','/v2/catalog-products/'+catalogId+'/mockup-styles?limit=100&selling_region_name=uk');\n  const groups=Array.isArray(stylesResponse?.data)?stylesResponse.data:[];\n  const options=[];\n  for(const group of groups) for(const style of Array.isArray(group?.mockup_styles)?group.mockup_styles:[]) {\n    const restricted=style?.restricted_to_variants;\n    if(Array.isArray(restricted)&&restricted.length&&!restricted.map(Number).includes(catalogVariantId)) continue;\n    const kind=String(style?.category_name||'');\n    if(!/flat|product only/i.test(kind)) continue;\n    const label=galleryViewName(style?.view_name||group.placement);\n    if(options.some(x=>x.label===label)) continue;\n    if(!Number.isInteger(Number(style?.id))) continue;\n    options.push({styleId:Number(style.id),label});\n  }\n  const priority=['Front','Back','Left sleeve','Right sleeve','Left side','Right side','Side','Top','Product view'];\n  options.sort((a,b)=>priority.indexOf(a.label)-priority.indexOf(b.label));\n  const selected=options.slice(0,5);\n  if(!selected.length) throw Error('no_flat_mockup_styles_for_product');\n  const placements=(Array.isArray(myv?.placements)&&myv.placements.length)?myv.placements:my.placements;\n  if(!Array.isArray(placements)||!placements.length) throw Error('saved_product_has_no_placements');\n  const req={format:'jpg',mockup_width_px:1000,products:[{source:'product',product_id:myId,variant_ids:[myv.id],mockup_style_ids:selected.map(x=>x.styleId),placements}]};\n  const created=await galleryPrintfulRequest('POST','/v2/mockup-tasks',req);\n  let tasks=Array.isArray(created?.data)?created.data:(created?.data?[created.data]:[]);\n  const ids=tasks.map(x=>Number(x.id)).filter(Number.isInteger);\n  if(!ids.length) throw Error('printful_gallery_task_not_created');\n  for(let attempt=0;attempt<13;attempt++){\n    if(tasks.every(t=>['completed','failed'].includes(String(t.status||'').toLowerCase()))) break;\n    await new Promise(resolve=>setTimeout(resolve,1500));\n    const polled=await galleryPrintfulRequest('GET','/v2/mockup-tasks?id='+ids.join(','));\n    const rows=Array.isArray(polled?.data)?polled.data:(polled?.data?[polled.data]:[]);\n    if(rows.length) tasks=rows;\n  }\n  const byStyle=new Map(selected.map(x=>[x.styleId,x.label]));\n  const images=[],seen=new Set();\n  for(const task of tasks){\n    for(const row of Array.isArray(task?.catalog_variant_mockups)?task.catalog_variant_mockups:[]){\n      if(Number(row.catalog_variant_id)!==catalogVariantId) continue;\n      for(const m of Array.isArray(row?.mockups)?row.mockups:[]){\n        const u=String(m?.mockup_url||'').trim();\n        if(!/^https:\\/\\//.test(u)||seen.has(u)) continue;\n        seen.add(u);images.push({mockup_url:u,view:byStyle.get(Number(m.style_id))||'Product view',color:v.color||null});\n      }\n    }\n  }\n  if(!images.length) throw Error('printful_mockup_task_' + String(tasks[0]?.status || 'no_images'));\n  return images;\n}\napp.get('/api/shop/gallery/:slug',async(req,res)=>{\n  const slug=String(req.params.slug||'');\n  if(!/^pf-\\d+$/.test(slug)) return res.status(400).json({error:'invalid_product'});\n  const catalog=await getPrintfulShopCatalog();\n  const product=catalog.find(p=>p.slug===slug);\n  if(!product) return res.status(404).json({error:'product_not_found'});\n  const variantId=String(req.query.variant_id||'');\n  const variant=product.variants?.find(v=>String(v.id)===variantId)||product.variants?.[0];\n  if(!variant)return res.status(404).json({error:'variant_not_found'});\n  const key=slug+':'+String(variant.color||variant.catalog_variant_id||variantId).toLowerCase();\n  const base=String(variant.mockup_url||variant.product_only_url||variant.image_url||'');\n  const initial=base.startsWith('https://')?[{mockup_url:base,view:'Product view',color:variant.color||null}]:[];\n  const cached=PRINTFUL_GALLERY_CACHE.get(key);\n  if(cached&&Date.now()-cached.at<(cached.ok?PRINTFUL_GALLERY_SUCCESS_MS:PRINTFUL_GALLERY_FAILURE_MS)){\n    const rest=cached.images.filter(m=>!initial.some(x=>x.mockup_url===m.mockup_url));\n    return res.json({mockups:initial.concat(rest),pending:false,gallery_available:cached.ok});\n  }\n  if(!PRINTFUL_GALLERY_RUNNING.has(key)){\n    const job=generatePrintfulGallery(product,variant).then(images=>{\n      PRINTFUL_GALLERY_CACHE.set(key,{at:Date.now(),ok:true,images});\n      console.log('Printful multi-angle gallery completed',slug,variant.color,images.length);\n    }).catch(e=>{\n      PRINTFUL_GALLERY_CACHE.set(key,{at:Date.now(),ok:false,images:[]});\n      console.error('Printful multi-angle gallery unavailable',slug,String(e?.message||e));\n    }).finally(()=>PRINTFUL_GALLERY_RUNNING.delete(key));\n    PRINTFUL_GALLERY_RUNNING.set(key,job);\n  }\n  return res.status(202).json({mockups:initial,pending:true,gallery_available:false});\n});\n";
